const input = $input.first().json || {};

function sanitizeObject(obj) {
  if (!obj || typeof obj !== 'object') return obj;
  if (Array.isArray(obj)) return obj.map(sanitizeObject);
  const clean = {};
  for (const key of Object.keys(obj)) {
    if (/pin|password|secret/i.test(key)) {
      clean[key] = '[REDACTED]';
    } else {
      clean[key] = sanitizeObject(obj[key]);
    }
  }
  return clean;
}

function safeStringify(value) {
  try {
    if (value === undefined || value === null) return '';
    if (typeof value === 'string') {
      if (/pin|password|secret/i.test(value)) return '[REDACTED]';
      return value;
    }
    const clean = sanitizeObject(value);
    return JSON.stringify(clean);
  } catch (e) {
    return '[unserializable detail]';
  }
}

const timestamp = new Date().toISOString();
const sessionId = input.session_id || '';
const employeeCode = input.employee_code || '';
const event = input.event || 'UNKNOWN_EVENT';
let detail = safeStringify(input.detail);
if (detail.length > 500) detail = detail.slice(0, 497) + '...';

return [{
  json: {
    Timestamp: timestamp,
    'Session ID': sessionId,
    'Employee Code': employeeCode,
    Event: event,
    Detail: detail
  }
}];
